import * as yargs from 'yargs'
import type { Argv } from 'yargs'
import { usage } from './usage'
import { epilogue } from './epilogue'
import { satisfies } from 'semver'
import { logger } from './logger'
import pkg from '../package.json'

try {
    yargs
        .check(() => {
            const neededVersion = pkg['engines']['node']
            if (!satisfies(process.version, neededVersion)) {
                logger.error(`now-sdk requires node version to be ${neededVersion}`)
                process.exit(1)
            }
            return true
        })
        .usage(usage)
        .option('debug', {
            describe: 'Print debug output',
            alias: 'd',
            default: false,
            type: 'boolean',
        })
        .command({
            command: 'auth',
            describe: 'Configure authentication to instance',
            builder: (y: Argv) => require('./command/auth').builder(y),
            handler: (argv) => require('./command/auth').handler(argv),
        })
        .command({
            command: 'init',
            describe:
                'Initialize a new ServiceNow custom application, apply a template to an existing application, or convert a legacy ServiceNow application from an instance or directory within the current directory structure.',
            aliases: ['create'],
            builder: (y: Argv) => require('./command/init').builder(y),
            handler: (argv) => require('./command/init').handler(argv),
        })
        .command({
            command: 'download <directory>',
            describe: 'Download application metadata from instance.',
            builder: (y: Argv) => require('./command/download').builder(y),
            handler: (argv) => require('./command/download').handler(argv),
        })
        .command({
            command: 'build [source]',
            describe: 'Compile sources into app files and generate installable package',
            builder: (y: Argv) => require('./command/build').builder(y),
            handler: (argv) => require('./command/build').handler(argv),
        })
        .command({
            command: 'install',
            describe: 'Install or update application on instance',
            aliases: ['deploy'],
            builder: (y: Argv) => require('./command/install').builder(y),
            handler: (argv) => require('./command/install').handler(argv),
        })
        .command({
            command: 'dependencies [sysIds..]',
            describe:
                'Download configured dependencies in now.config.json and typescript type definitions for use in the application',
            builder: (y: Argv) => require('./command/dependencies').builder(y),
            handler: (argv) => require('./command/dependencies').handler(argv),
        })
        .command({
            command: 'transform',
            describe: 'Download and convert XML records from instance or from a local path into Fluent source code',
            builder: (y: Argv) => require('./command/transform').builder(y),
            handler: (argv) => require('./command/transform').handler(argv),
        })
        .command({
            command: 'run [script]',
            describe: false,
            builder: (y: Argv) => require('./command/run').builder(y),
            handler: (argv) => require('./command/run').handler(argv),
        })
        .command({
            command: 'clean [source]',
            describe: 'Clean output directory',
            builder: (y: Argv) => require('./command/clean').builder(y),
            handler: (argv) => require('./command/clean').handler(argv),
        })
        .command({
            command: 'pack [source]',
            describe: 'Zip built app into installable artifact',
            builder: (y: Argv) => require('./command/pack').builder(y),
            handler: (argv) => require('./command/pack').handler(argv),
        })
        .command({
            command: 'explain [topic]',
            describe: 'Display documentation for a Fluent SDK topic',
            builder: (y: Argv) => require('./command/explain').builder(y),
            handler: (argv) => require('./command/explain').handler(argv),
        })
        .command({
            command: 'move',
            describe: false,
            builder: (y: Argv) => require('./command/move-to-app').builder(y),
            handler: (argv) => require('./command/move-to-app').handler(argv),
        })
        .command({
            command: 'query <table>',
            describe: 'Query records from a ServiceNow table on the instance',
            builder: (y: Argv) => require('./command/query').builder(y),
            handler: (argv) => require('./command/query').handler(argv),
        })
        .demandCommand()
        .middleware(async (argv) => {
            if (argv.debug) {
                logger.setLevel('debug')
                logger.debug('Debug logging enabled')
            }
        })
        .epilogue(epilogue)
        .strictCommands()
        .help()
        .updateStrings({
            'Positionals:': 'Parameters:',
        })
        .alias('h', 'help')
        .alias('v', 'version')
        .scriptName('now-sdk').argv
} catch (error) {
    logger.error(error)
}
